INSERT INTO `novel` VALUES (1, 14, 0, 2, 'http://localhost:8081/upload/novel_cover/693d01f3-c88d-4cdf-8dec-b42c889761f2.png', '2025-12-31 21:00:53.320273', '苏念是顶流演员陆景琛的专属造型师，温柔细腻，手艺精湛，陪伴他从默默无闻到星光璀璨，却始终把自己的心意，藏在身后，做他最坚实的后盾。陆景琛是娱乐圈顶流，颜值与实力并存，清冷疏离，不擅表达，却唯独对苏念，格外不一样。他习惯了她的陪伴，习惯了她的手艺，习惯了她在身边的每一刻，却在一次颁奖典礼上，看到她默默转身离开的背影，才懂自己早已在不知不觉中，爱上了这个一直默默守护他的女孩。聚光灯下，他万众瞩目，却只想奔赴她；星光璀璨中，他名利双收，却只想予她温柔。原来，最好的星光，是你；最美的余生，是和你一起。', NULL, 0, 'PUBLISHED', '予你星光，赴你余生', 3, '2026-04-04 01:36:01.035585', 0, NULL, 0, 'http://localhost:8081/upload/novel_cover/693d01f3-c88d-4cdf-8dec-b42c889761f2.png', '苏念是顶流演员陆景琛的专属造型师，温柔细腻，手艺精湛，陪伴他从默默无闻到星光璀璨，却始终把自己的心意，藏在身后，做他最坚实的后盾。陆景琛是娱乐圈顶流，颜值与实力并存，清冷疏离，不擅表达，却唯独对苏念，格外不一样。他习惯了她的陪伴，习惯了她的手艺，习惯了她在身边的每一刻，却在一次颁奖典礼上，看到她默默转身离开的背影，才懂自己早已在不知不觉中，爱上了这个一直默默守护他的女孩。聚光灯下，他万众瞩目，却只想奔赴她；星光璀璨中，他名利双收，却只想予她温柔。原来，最好的星光，是你；最美的余生，是和你一起。鹅', 'PENDING', '予你星光，赴你余生', 3, NULL);
INSERT INTO `novel` VALUES (16, 14, 3, 19, 'http://localhost:8081/upload/novel_cover/3f2b8e2c-8667-42f4-a75e-ba63f60d9ed0.png', '2026-01-19 03:31:33.220156', '林知夏是医院的急诊科护士，每天在生死边缘奔波，性格坚韧乐观，习惯用温柔包裹自己的疲惫，却在一次次加班熬夜、应对突发状况中，渐渐感到力不从心。沈聿辰是医院最年轻的外科主任医师，冷静果决，医术精湛，是全院公认的“冰山男神”，却因一次医疗纠纷，内心背负着不为人知的压力。一次急诊抢救中，林知夏的沉着冷静打动了沈聿辰；无数个深夜的值班时光，两人相互陪伴、彼此救赎，他替她挡下无理的指责，她陪他走出心理的阴霾。原来，再冰冷的冰山，也会被温柔融化；再疲惫的奔赴，也会有暖意同行，心向暖意，便会遇见温柔，遇见爱', '2026-03-12 22:25:24.559326', 350, 'PUBLISHED', '心向暖意', 2, '2026-04-08 05:38:20.390376', 7032, NULL, 0, 'http://localhost:8081/upload/novel_cover/3f2b8e2c-8667-42f4-a75e-ba63f60d9ed0.png', '林知夏是医院的急诊科护士，每天在生死边缘奔波，性格坚韧乐观，习惯用温柔包裹自己的疲惫，却在一次次加班熬夜、应对突发状况中，渐渐感到力不从心。沈聿辰是医院最年轻的外科主任医师，冷静果决，医术精湛，是全院公认的“冰山男神”，却因一次医疗纠纷，内心背负着不为人知的压力。一次急诊抢救中，林知夏的沉着冷静打动了沈聿辰；无数个深夜的值班时光，两人相互陪伴、彼此救赎，他替她挡下无理的指责，她陪他走出心理的阴霾。原来，再冰冷的冰山，也会被温柔融化；再疲惫的奔赴，也会有暖意同行，心向暖意，便会遇见温柔，遇见爱', 'APPROVED', '心向暖意', 2, NULL);
INSERT INTO `novel` VALUES (25, 16, 1, 6, 'http://localhost:8081/upload/novel_cover/6e629f89-f799-4061-9598-153ce5af8886.png', '2026-03-12 18:39:06.334931', '苏清颜是昆仑仙宗最不起眼的外门弟子，资质平庸，却心性坚韧，执着于修仙问道，每日在昆仑后山勤修不辍，只求能窥得仙门真谛。谢云珩是昆仑仙宗的首席大弟子，修为高深，仙姿卓绝，清冷出尘，是整个仙门弟子敬仰的存在，却因当年为救仙宗，身负重伤，灵力受损，常年独居在昆仑云深处，不问世事。一次后山修炼，苏清颜意外误入谢云珩的居所，惊扰了这位隐世的仙者。他本欲驱她离开，却被她的坚韧和纯粹打动，破例收她为徒，教她修炼心法，助她突破瓶颈。朝夕相处间，清冷仙者的温柔，藏在每一次指导、每一次守护中；平凡弟子的执着，暖了他孤寂多年的心。可仙门危机暗藏，当年重伤他的魔教余孽卷土重来，妄图夺取昆仑秘宝，颠覆仙门。谢云珩为守护', '2026-04-02 07:16:51.296673', 30, 'PUBLISHED', '云深归处，卿心向仙', 5, '2026-04-13 22:11:24.274928', 1297, NULL, 1, 'http://localhost:8081/upload/novel_cover/6e629f89-f799-4061-9598-153ce5af8886.png', '苏清颜是昆仑仙宗最不起眼的外门弟子，资质平庸，却心性坚韧，执着于修仙问道，每日在昆仑后山勤修不辍，只求能窥得仙门真谛。谢云珩是昆仑仙宗的首席大弟子，修为高深，仙姿卓绝，清冷出尘，是整个仙门弟子敬仰的存在，却因当年为救仙宗，身负重伤，灵力受损，常年独居在昆仑云深处，不问世事。一次后山修炼，苏清颜意外误入谢云珩的居所，惊扰了这位隐世的仙者。他本欲驱她离开，却被她的坚韧和纯粹打动，破例收她为徒，教她修炼心法，助她突破瓶颈。朝夕相处间，清冷仙者的温柔，藏在每一次指导、每一次守护中；平凡弟子的执着，暖了他孤寂多年的心。可仙门危机暗藏，当年重伤他的魔教余孽卷土重来，妄图夺取昆仑秘宝，颠覆仙门。谢云珩为守护', 'APPROVED', '云深归处，卿心向仙', 5, NULL);
INSERT INTO `novel` VALUES (29, 14, 0, 0, 'http://localhost:8081/upload/novel_cover/30886bae-c1aa-4387-90d0-88fe25be7877.png', '2026-03-19 16:40:42.302678', '苏晚是出版社不起眼的文字编辑，性格温柔却有韧性，习惯把情绪藏在眼底，唯一的执念是做好手中的每一本书。陆时衍是业内知名的建筑设计师，清冷寡言，行事果决，浑身带着生人勿近的疏离感，却在一次出版社合作中，意外注意到这个总是安安静静、却能精准捕捉文字里细腻情绪的女孩。一次加班后的晚风里，他替她挡开喧嚣的人群；无数个修改稿件的深夜，他默默送来温热的咖啡；他以为自己只是习惯了她的存在，却在看到她和别人谈笑风生时，才懂心动早已在不知不觉中，被晚风裹挟着，撞进了心底。原来清冷的晚风，终会遇见属于自己的骄阳，而他的骄阳，从始至终都是她。', '2026-04-03 06:31:48.912727', 28, 'PUBLISHED', '晚风遇骄阳', 1, '2026-04-03 06:31:48.912727', 7498, NULL, 2, 'http://localhost:8081/upload/novel_cover/30886bae-c1aa-4387-90d0-88fe25be7877.png', '苏晚是出版社不起眼的文字编辑，性格温柔却有韧性，习惯把情绪藏在眼底，唯一的执念是做好手中的每一本书。陆时衍是业内知名的建筑设计师，清冷寡言，行事果决，浑身带着生人勿近的疏离感，却在一次出版社合作中，意外注意到这个总是安安静静、却能精准捕捉文字里细腻情绪的女孩。一次加班后的晚风里，他替她挡开喧嚣的人群；无数个修改稿件的深夜，他默默送来温热的咖啡；他以为自己只是习惯了她的存在，却在看到她和别人谈笑风生时，才懂心动早已在不知不觉中，被晚风裹挟着，撞进了心底。原来清冷的晚风，终会遇见属于自己的骄阳，而他的骄阳，从始至终都是她。', 'APPROVED', '晚风遇骄阳', NULL, NULL);
INSERT INTO `novel` VALUES (31, 14, 0, 0, 'http://localhost:8081/upload/novel_cover/20997d46-02fd-40b4-b574-05d39dffd4b0.png', '2026-04-02 06:30:33.853468', '灵汐是青丘最不起眼的小狐妖，修为低微，性格单纯善良，却因一次意外，误入玄渊秘境，遇见了被封印千年的玄渊上神。玄渊上神是上古神祇，实力强大，清冷孤高，因当年平定三界战乱，被奸人陷害，封印于玄渊秘境，千年孤寂，满心荒芜。灵汐的出现，像一束微光，照亮了他千年孤寂的时光，她单纯的笑容，温柔的陪伴，一点点融化了他冰封的心。他护她周全，教她修炼，助她成长；她陪他度过孤寂，解他心结，暖他心房。可三界危机再起，当年陷害他的奸人再次出现，妄图颠覆三界，他为了守护三界，也为了守护她，不得不解开封印，重临三界。这一次，他不再是孤寂的上神，他有了想要守护的人，哪怕付出一切，哪怕魂飞魄散，他也要护她一世安稳，与她情定三', NULL, 0, 'PENDING_REVIEW', '玄渊遇卿，情定三生', 4, '2026-04-04 01:36:04.007484', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `novel` VALUES (34, 14, 0, 0, 'http://localhost:8081/upload/novel_cover/ce9043cc-92c4-4968-8e41-d80e49002137.png', '2026-05-31 07:55:03.775502', '灵根残缺的凡尘少年，自幼被仙门弃于山野，本以为一生碌碌无为，却意外拾得上古残卷，觉醒世间罕见混沌灵体。昔日欺辱他的同门、冷眼相待的师尊、妄图掠夺机缘的邪魔，皆在他步步登仙之路下俯首。仙途漫漫，恩怨纠缠，一边是大道长生，一边是俗世情长，当剑锋指向九天之上，他终将抉择：是做逍遥散仙，还是执手一人，共渡这万丈红尘？', NULL, 0, 'DRAFT', '仙骨尘缘', 5, '2026-05-31 07:55:03.775502', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
